import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const u=JSON.parse('{"title":"1963年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1963年/核心总结.md","filePath":"01_letters/1963年/核心总结.md"}'),l={name:"01_letters/1963年/核心总结.md"};function i(n,a,s,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1963年-核心总结" tabindex="-1">1963年 核心总结 <a class="header-anchor" href="#_1963年-核心总结" aria-label="Permalink to &quot;1963年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1963年是又一个辉煌的年份。道琼斯指数上涨20.7%，而巴菲特合伙企业回报率高达38.7%，连续第二年大幅跑赢市场。登普斯特农机制造公司于7月完成出售，每股价格约80美元，这笔交易的圆满收官为合伙企业带来了可观的利润。整体而言，1963年充分体现了巴菲特&quot;低估+催化剂&quot;投资逻辑的有效性——找到被低估的标的，然后通过各种方式（管理改善、出售、并购）释放价值。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>德州国家石油（TNP，Texas National Petroleum）套利案例是本年最引人注目的投资案例之一。TNP是一家小型石油公司，其资产被低估，存在明显的并购或套利机会。巴菲特通过精密计算风险收益比，在确定性较高的情况下投入重金，最终获得了可观的套利回报。这个案例展示了巴菲特在二级市场投资之外，对事件驱动型机会的敏锐捕捉能力。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特在信中进一步明确了&quot;定性&quot;与&quot;定量&quot;分析的关系。他承认，有些投资机会难以量化，但直觉和商业判断同样重要。同时，他再次强调：不亏钱的重要性永远排在赚钱之前。TNP套利案例体现了他的风险控制思维：在信息充分、风险可控的前提下，才重仓介入。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>登普斯特的出售是巴菲特与哈里·博特尔合作成果的集中体现。通过博特尔的有效管理，公司资产得到充分释放，最终以约每股80美元的价格完成退出，买家获得了稳定回报。此外，TNP项目中涉及的律师、金融顾问等中间人也在套利流程中发挥了关键作用，进一步拓展了巴菲特的合作网络。</p>',9)])])}const p=e(l,[["render",i]]);export{u as __pageData,p as default};
